E('audit','GET','/admin/moderation-actions','Tra nhật ký quyết định',admin,null,'ModerationAction[] {actor,action,target,reason,occurredAt}','Lọc actor/action/target/from/to; chỉ đọc, không có endpoint sửa/xóa audit. Snapshot che dữ liệu nhạy cảm.', '',{list:true});
