E('file-storage','POST','/files/upload-sessions','Xin phiên upload theo mục đích',self,schema('UploadSession',[f('purpose','enum',true,'AVATAR/POST_IMAGE/IDENTITY/LANDLORD_PROOF/CONTRACT/REPORT_EVIDENCE/CHAT_IMAGE.','LANDLORD_PROOF'),f('originalName','string',true,'≤255 ký tự; không dùng làm storage key.','minh-chung.pdf'),f('mimeType','string',true,'Allowlist theo purpose, kiểm tra lại bytes.','application/pdf'),f('sizeBytes','integer',true,'Proof nhà: 1–5.242.880 bytes; mục đích khác theo D05.',125000),f('sha256','string',true,'64 ký tự hex; xác minh sau upload.','a'.repeat(64))]),'{fileId,status:STAGED,uploadUrl,expiresAt,requiredHeaders}','Server tự owner/storage_key/PRIVATE cho giấy tờ, URL ký ngắn hạn; không tin visibility client. Chưa có object storage thật; PUT bytes tới uploadUrl là giao thức kho, không endpoint nghiệp vụ mới.', '',{decision:'D05'});
E('file-storage','POST','/files/{fileId}/complete','Xác minh tệp upload hoàn tất',self,null,'File {id,status:ACTIVE,purpose,sizeBytes}','Chỉ chủ tệp STAGED; HEAD/checksum/MIME magic/quét nội dung từ kho; chỉ ACTIVE khi đạt. Không coi tên tệp client là đã upload.');
E('file-storage','GET','/files/{fileId}','Metadata tệp được phép xem',self,null,'File metadata an toàn; không storageKey/raw bucket URL','Chủ hoặc người có quyền qua hồ sơ/report/contract/chat; kiểm tra cả purpose/context/status/hạn lưu. Đoán ID không cấp quyền.');
E('file-storage','POST','/files/{fileId}/download-links','Cấp URL đọc riêng tư có hạn',self,null,'{downloadUrl,expiresAt}','Kiểm tra role + liên kết nghiệp vụ tại thời điểm cấp; TTL ngắn, không cache công khai; admin được đọc hồ sơ phục vụ xét duyệt.');
E('file-storage','DELETE','/files/{fileId}','Xóa mềm tệp chưa bị giữ làm chứng cứ',self,null,'File {id,status:DELETED}','Chỉ chủ, kiểm tra tham chiếu/retention. Proof nhà đã nộp bất biến, không cho đổi bytes/visibility/xóa; tệp hợp đồng/giấy tờ giữ theo policy D05. Không xóa thẳng object trước khi DB cho phép.', '',{decision:'D05'});

